print("=" * 80)
print("CONDITIONAL GRANGER CAUSALITY: token_entropy vs ECE → diversity")
print("=" * 80)

all_results = {}
missing = []

for exp_name, path in EXPERIMENTS.items():
    if not os.path.exists(path):
