        tests["uncond_ece"] = unconditional_granger(df, "ece", downstream)
        tests["cond_entropy_given_ece"] = conditional_granger(df, "token_entropy", downstream, "ece")
        tests["cond_ece_given_entropy"] = conditional_granger(df, "ece", downstream, "token_entropy")
        tests["joint"] = joint_granger(df, ["token_entropy", "ece"], downstream)

        exp_results["tests"][downstream] = tests

        for test_name, lag_results in tests.items():
            if lag_results is None:
                continue
            for lag, r in lag_results.items():
                p = r.get("p_value", np.nan)
                sig = "***" if p < 0.01 else "**" if p < 0.05 else "*" if p < 0.10 else ""
                if not np.isnan(p):
                    print(f"    {downstream:<12} | {test_name:<25} | lag={lag} | p={p:.4f} {sig}")

